#include "scarlett_cpu64.hpp"
#include <cassert>
#include <iostream>
using namespace genesis;
int main(){GuestMemory64 m;assert(m.map(0x1000,4096,7)==GuestMemory64::Fault::none);Cpu64State i;i.gpr[0]=uint64_t(-12);i.xmm[0].fill(0x55);i.ymmHigh[0].fill(0xff);i.cf=true;auto run=[&](auto b){assert(m.write(0x1000,b)==GuestMemory64::Fault::none);auto s=executeGuest64(m,0x1000,1,0x1900,nullptr,0,0,0,0,&i);assert(s.steps==1&&s.cf);for(auto v:s.ymmHigh[0])assert(v==0);return s;};for(unsigned pp:{2u,3u}){auto s=run(std::array<uint8_t,5>{0xc4,0xe1,uint8_t(0xf8|pp),0x2a,0xc0});if(pp==2){float v;memcpy(&v,s.xmm[0].data(),4);assert(v==-12);}else{double v;memcpy(&v,s.xmm[0].data(),8);assert(v==-12);}for(unsigned j=pp==2?4:8;j<16;++j)assert(s.xmm[0][j]==0x55);for(unsigned op:{0x58u,0x59u,0x5cu,0x5eu}){double expected=op==0x58?8:op==0x59?12:op==0x5c?4:3;if(pp==2){float a=6,b=2;memcpy(i.xmm[0].data(),&a,4);memcpy(i.xmm[1].data(),&b,4);}else{double a=6,b=2;memcpy(i.xmm[0].data(),&a,8);memcpy(i.xmm[1].data(),&b,8);}s=run(std::array<uint8_t,4>{0xc5,uint8_t(0xf8|pp),uint8_t(op),0xc1});if(pp==2){float v;memcpy(&v,s.xmm[0].data(),4);assert(v==expected);}else{double v;memcpy(&v,s.xmm[0].data(),8);assert(v==expected);}}i.xmm[0].fill(0x55);}std::cout<<"V58 scalar arithmetic tests passed\n";}
